import { useState, useEffect } from "react";
import {
  crearEvaluacionPsico,
  actualizarEvaluacionPsico,
} from "../../servicios/evaluacionPsico";
import { listarEvaluacionesIntegrales } from "../../servicios/evaluacionIntegral";
import { crearSubdimensionItem } from "../../servicios/subdimensionItems";

const ITEMS_COMUNICATIVAS = [
  { codigo: 1, descripcion: "Se comunica de forma espontánea" },
  { codigo: 2, descripcion: "Se comunica de forma guiada" },
  { codigo: 3, descripcion: "Participa en conversaciones espontáneamente" },
  { codigo: 4, descripcion: "Pronunciación y estructura claras" },
  { codigo: 5, descripcion: "Uso de oraciones completas" },
];

function EvaluacionPsicoForm({ evaluacion, onSuccess }) {
  const isEdit = !!evaluacion;
  const [evaluacionIntegral, setEvaluacionIntegral] = useState(
    evaluacion?.evaluacion_integral || ""
  );
  const [evaluador, setEvaluador] = useState(evaluacion?.evaluador || "");
  const [fecha, setFecha] = useState(evaluacion?.fecha || "");
  const [observaciones, setObservaciones] = useState(
    evaluacion?.observaciones || ""
  );

  const [integrales, setIntegrales] = useState([]);

  const [comunicativas, setComunicativas] = useState(
    ITEMS_COMUNICATIVAS.reduce(
      (acc, item) => ({ ...acc, [item.codigo]: 0 }),
      {}
    )
  );

  useEffect(() => {
    listarEvaluacionesIntegrales().then(setIntegrales);
  }, []);

  const handleRadioChange = (codigo, valor) => {
    setComunicativas((prev) => ({ ...prev, [codigo]: valor }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const payload = {
      evaluacion_integral: evaluacionIntegral,
      evaluador,
      fecha,
      observaciones,
    };

    try {
      let resp;

      if (isEdit) {
        resp = await actualizarEvaluacionPsico(evaluacion.id, payload);
      } else {
        resp = await crearEvaluacionPsico(payload);
      }

      const evalId = resp.id;

      // Crear los ítems de la primera subdimensión
      for (const item of ITEMS_COMUNICATIVAS) {
        await crearSubdimensionItem({
          evaluacion: evalId,
          area: "Habilidades Comunicativas",
          descripcion: item.descripcion,
          valor: Number(comunicativas[item.codigo]),
        });
      }

      alert("Evaluación guardada exitosamente");
      if (onSuccess) onSuccess();

    } catch (error) {
      console.error(error);
      alert("❌ Error al guardar la evaluación");
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      {/* Campo Evaluación integral */}
      <label>Evaluación integral:</label>
      <select
        value={evaluacionIntegral}
        onChange={(e) => setEvaluacionIntegral(e.target.value)}
      >
        <option value="">-- Selecciona --</option>
        {integrales.map((ei) => (
          <option key={ei.id} value={ei.id}>
            {ei.id}
          </option>
        ))}
      </select>

      <br />

      <label>Evaluador:</label>
      <input
        value={evaluador}
        onChange={(e) => setEvaluador(e.target.value)}
      />

      <br />

      <label>Fecha:</label>
      <input type="date" value={fecha} onChange={(e) => setFecha(e.target.value)} />

      <br />
      <hr />

      {/* ---- SUBDIMENSIÓN I ---- */}

      <h3>I. Habilidades Comunicativas</h3>

      <table border="1" cellPadding="4" width="100%">
        <thead>
          <tr>
            <th>Ítem</th>
            <th>1</th>
            <th>2</th>
            <th>3</th>
            <th>4</th>
            <th>0</th>
          </tr>
        </thead>

        <tbody>
          {ITEMS_COMUNICATIVAS.map((item) => (
            <tr key={item.codigo}>
              <td>{item.descripcion}</td>

              {[1, 2, 3, 4, 0].map((val) => (
                <td key={val}>
                  <input
                    type="radio"
                    name={`item-${item.codigo}`}
                    value={val}
                    checked={comunicativas[item.codigo] === val}
                    onChange={() => handleRadioChange(item.codigo, val)}
                  />
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>

      <br />

      <label>Observaciones:</label>
      <textarea
        rows={3}
        style={{ width: "100%" }}
        value={observaciones}
        onChange={(e) => setObservaciones(e.target.value)}
      />

      <br />
      <button type="submit">
        {isEdit ? "Actualizar" : "Crear evaluación"}
      </button>
    </form>
  );
}

export default EvaluacionPsicoForm;
